loadTextOn = function (state, text, x = 0, y = 0)
{
    state.loadLines(belt.linesForText(text))
    return state.setMainCursor(x,y)
}

loadText = function (text, x = 0, y = 0)
{
    return loadTextOn(s,text,x,y)
}

freshText = function (text, x = 0, y = 0)
{
    s.clearHistory()
    return loadText(text,x,y)
}

runEx = function (text, ex, x = 0, y = 0, nvm = null)
{
    gm = (nvm != null ? nvm : new novim(s))
    freshText(text,x,y)
    gm.runEx(ex)
    return kseg.str(s.s.lines)
}

endSess = function ()
{
    return delete global.ked_session
}

startNovim = function (state)
{
    mode.modes.novim = novim
    return mode.start(state,'novim')
}

stopNovim = function (state)
{
    return mode.stop(state,'novim')
}

done = function (state)
{
    stopNovim(state)
    return endSess()
}

pressKey = function (state, c)
{
    return mode.handleKey(state,c,{combo:c,char:c})
}

pressFor = function (state)
{
    return function (c)
    {
        return pressKey(state,c)
    }
}
